mapper.select:
select * from B
from(
  select rownum RN, A.*
  from(
    select
      MEM.ID as USER_ID
      ,MEM.NAME
      ,MEM.NICKNAME
      ,MEM.STATUS
      ,CON.CONSULTANT_NO
      ,ORG.NAME as ORG_NAME
      ,count(*) as STUDENT_COUNT
    from CONSULTANT CON
    left join MEMBER MEM on (MEM.MEMBER_NO = CON.CONSULTANT_NO)
    left join ORGANIZATION ORG on (ORG.ORG_NO = CON.ORG_NO)
    left join CONSULTANT_STUDENT CS on (CON.CONSULTANT_NO = CS.CONSULTANT_NO)


        and MEM.NAME = #{name}


        and MEM.NICKNAME = #{nickname}


        and MEM.STATUS = #{status}


        and ORG.NAME = #{orgName}


        and exists (
          select 1
          from CONSULTANT CON2
          left join CONSULTANT_STUDENT CS2 on (CON2.CONSULTANT_NO = CS2.CONSULTANT_NO)
          left join STUDENT STU2 on (STU2.STUDENT_NO = CS2.STUDENT_NO)
          where CON2.CONSULTANT_NO = CON.CONSULTANT_NO
          and STU2.NAME = #{studentName}
        )


    group by
      MEM.ID
      ,MEM.NAME
      ,MEM.NICKNAME
      ,MEM.STATUS
      ,CON.CONSULTANT_NO
      ,ORG.NAME
    order by CONSULTANT_NO desc
  ) A
  where rownum <= #{endRow}
) B
where RN >= #{startRow}

select count(*)
from CONSULTANT CON
left join MEMBER MEM on (MEM.MEMBER_NO = CON.CONSULTANT_NO)
left join ORGANIZATION ORG on (ORG.ORG_NO = CON.ORG_NO)


    and MEM.NAME = #{name}


    and MEM.NICKNAME = #{nickname}


    and MEM.STATUS = #{status}


    and ORG.NAME = #{orgName}


    and exists (
      select 1
      from CONSULTANT CON2
      left join CONSULTANT_STUDENT CS2 on (CON2.CONSULTANT_NO = CS2.CONSULTANT_NO)
      left join STUDENT STU2 on (STU2.STUDENT_NO = CS2.STUDENT_NO)
      where CON2.CONSULTANT_NO = CON.CONSULTANT_NO
      and STU2.NAME = #{studentName}
    )
